/* @lc app=leetcode id=1568 lang=kotlin */ class Solution { fun minDays(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> DeepRecursiveFunction<Pair<Int, IntArray>, Unit> { (curr, vis) -> (curr / n to curr % n).let { (r, c) -> vis.also { it[curr] = 1 }.run { listOf(r - 1 to c, r + 1 to c, r to c - 1, r to c + 1).forEach { (nr, nc) -> if (nr in 0 until m && nc in 0 until n && grid[nr][nc] == 1 && vis[nr * n + nc] == 0) callRecursive(nr * n + nc to vis) } } } }.let { dfs -> { IntArray(m * n).let { vis -> (0 until m * n).count { i -> (grid[i / n][i % n] == 1 && vis[i] == 0).also { if (it) dfs(i to vis) } } } }.let { countIslands -> if (countIslands() != 1) 0 else if (grid.indices.any { r -> grid[0].indices.any { c -> grid[r][c] == 1 && grid[r][c].let { grid[r][c] = 0 }.run { countIslands() != 1 }.also { grid[r][c] = 1 } } }) 1 else 2 } } } } }